INSERT INTO lessons (id, chapter_id, code, name, page, sort_order, knowledge_json) VALUES
(gen_random_uuid(), 'b2a55b2b-1a3b-3a1a-7a7a-0a1b2c3d4e5f', 'P_4', 'Mở đầu', 4, 4, $JSON$
{
  "content": [
    "# HƯỚNG DẪN SỬ DỤNG SÁCH",
    "",
    "Cuốn sách *Hoá học 12* nằm trong bộ sách Kết nối tri thức với cuộc sống của Nhà xuất bản Giáo dục Việt Nam. Cuốn sách có 8 chương, 30 bài học và được thiết kế thành các hoạt động học tập. Các hoạt động học tập trong mỗi bài học được chỉ dẫn cụ thể như sau:",
    "",
    "[Hình ảnh minh hoạ một trang sách với các chú thích]",
    "**MỞ ĐẦU**: Câu hỏi gợi mở, thu hút sự quan tâm tìm hiểu bài học mới.",
    "**HÌNH THÀNH KIẾN THỨC MỚI**: Học sinh thực hiện các hoạt động khám phá, tìm hiểu kết hợp các kiến thức đã có và được cung cấp để rút ra các nội dung hoá học.",
    "**Hoạt động nghiên cứu**: Học sinh thực hiện các nhiệm vụ học tập và trực tiếp tham gia vào quá trình khám phá, phát hiện, hình thành và vận dụng kiến thức mới.",
    "**Hoạt động thí nghiệm**: Học sinh thực hiện các thí nghiệm hoá học để phát hiện, hình thành kiến thức mới, phát triển năng lực nghiên cứu khoa học, thực hành thí nghiệm, khẳng định niềm tin vào khoa học.",
    "**EM CÓ BIẾT**: Mở rộng kiến thức, kết nối tri thức với cuộc sống.",
    "**CÂU HỎI VÀ BÀI TẬP**: Giúp các em hiểu rõ vấn đề của bài học, nâng cao năng lực tư duy, ứng dụng kiến thức đã học được.",
    "**EM ĐÃ HỌC**: Kiến thức, kĩ năng cơ bản của bài học.",
    "**EM CÓ THỂ**: Vận dụng kiến thức, kĩ năng đã học.",
    "",
    "*Hãy bảo quản, giữ gìn sách giáo khoa để dành tặng các em học sinh lớp sau!*",
    "",
    "2",
    ""
  ]
}
$JSON$);

INSERT INTO lessons (id, chapter_id, code, name, page, sort_order, knowledge_json) VALUES
(gen_random_uuid(), 'b2a55b2b-1a3b-3a1a-7a7a-0a1b2c3d4e5f', 'P_5', 'Mở đầu', 5, 5, $JSON$
{
  "content": [
    "# LỜI NÓI ĐẦU",
    "",
    "Trong Chương trình giáo dục phổ thông, môn Hoá học thuộc nhóm các môn khoa học tự nhiên. Ở bậc học Trung học phổ thông, Hoá học là môn học được học sinh lựa chọn theo định hướng nghề nghiệp, sở thích và năng lực của bản thân.",
    "",
    "Môn Hoá học giúp cho học sinh hình thành, phát triển và dần hoàn thiện năng lực: nhận thức hoá học, nghiên cứu khoa học, tìm hiểu tự nhiên, vận dụng kiến thức để giải thích các quá trình tự nhiên hay áp dụng vào sản xuất phục vụ đời sống. Từ đó giúp cho học sinh biết tôn trọng quy luật tự nhiên, biết ứng xử với thiên nhiên phù hợp với yêu cầu phát triển bền vững, góp phần giúp học sinh lựa chọn nghề nghiệp phù hợp với năng lực, sở thích và điều kiện, hoàn cảnh của bản thân.",
    "",
    "Nội dung cuốn sách giáo khoa *Hoá học 12* bám sát Chương trình giáo dục phổ thông 2018, được thiết kế thành 8 chương bao gồm các nội dung về Kiến thức cơ sở hoá học chung, Hoá học hữu cơ và Hoá học vô cơ. Phần Kiến thức cơ sở hoá học chung cung cấp kiến thức về pin điện và điện phân. Phần Hoá học hữu cơ cung cấp kiến thức về các hợp chất có nhiều trong tự nhiên như ester, lipid, carbohydrate, các hợp chất chứa nitrogen hay các hợp chất được sử dụng làm vật liệu phục vụ đời sống. Phần Hoá học vô cơ cung cấp kiến thức về các nguyên tố kim loại, hợp chất phức của kim loại. Những nội dung này giúp cho học sinh phát triển, hoàn thiện kiến thức, kĩ năng thực hành, làm cơ sở để học sinh có thể học tập, làm việc và nghiên cứu khoa học.",
    "",
    "Nội dung và kiến thức trong cuốn sách giáo khoa *Hoá học 12* được lựa chọn sao cho các thầy, cô giáo có thể tổ chức các hoạt động giáo dục phù hợp với sở trường, năng lực của học sinh, từ đó các em có thể phát triển năng lực tự học, năng lực nghiên cứu tìm hiểu tự nhiên, đồng thời góp phần thực hiện phân hoá sâu trong quá trình giáo dục.",
    "",
    "Chúng tôi hi vọng cuốn sách sẽ là người bạn đồng hành tin cậy, giúp các em học sinh nuôi dưỡng tình yêu hoá học và có định hướng nghề nghiệp phù hợp trong tương lai.",
    "",
    "**Các tác giả**",
    "",
    "3",
    ""
  ]
}
$JSON$);

