INSERT INTO lessons (id, chapter_id, code, name, page, sort_order, knowledge_json) VALUES
('10000001-0011-0001-0000-000000000000', '10000001-0011-0001-0000-000000000000', 'B0', 'Bìa sách', 0, 0, $JSON$
